create function private_hns_women_release.source_deadline(p_source_competition_id text,p_round int,p_fixtures jsonb,p_offset int)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare f jsonb;e private_hns_women_release.fixture_catalog%rowtype;ids text[]:=array[]::text[];day date;clock time;local_time timestamp;instant timestamptz;candidate timestamptz;earliest timestamptz;first_day date;reason text;winner text;candidates jsonb:='[]';expected int;
begin
 select count(*)into expected from private_hns_women_release.fixture_catalog where source_competition_id=p_source_competition_id and internal_round=p_round;
 if p_offset is distinct from 6 or expected=0 or jsonb_typeof(p_fixtures)is distinct from 'array'or jsonb_array_length(p_fixtures)<>expected then raise exception 'HNS_RELEASE: complete reviewed round/offset required';end if;
 for f in select value from jsonb_array_elements(p_fixtures)loop
  select *into e from private_hns_women_release.fixture_catalog where source_match_id=f->>'id'and source_competition_id=p_source_competition_id and internal_round=p_round;
  if e.source_match_id is null or e.source_match_id=any(ids)or (f->>'krog')::int is distinct from p_round
   or f->'sourceRound'is distinct from e.document->'sourceRound'or f->'sourcePhase'is distinct from e.document->'sourcePhase'
   or f->'domaciId'is distinct from e.document->'domaciId'or f->'gostjeId'is distinct from e.document->'gostjeId'
   or f->'domaci'is distinct from e.document->'domaci'or f->'gostje'is distinct from e.document->'gostje'
  then raise exception 'HNS_RELEASE: native fixture/phase/club identity differs';end if;
  ids:=array_append(ids,e.source_match_id);
  if f->>'datum'is null then
   if e.source_match_id<>'114471614'or f->'postponed'is distinct from 'true'::jsonb or f->>'ura'is not null then raise exception 'HNS_RELEASE: missing source date is not reviewed explicit postponement';end if;
   continue;
  end if;
  if f->>'datum'!~'^\d{4}-\d{2}-\d{2}$'or(f->>'ura'is not null and f->>'ura'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$')then raise exception 'HNS_RELEASE: invalid source date/time';end if;
  day:=(f->>'datum')::date;
  if day<make_date(left(e.season,4)::int,7,1)or day>=make_date(left(e.season,4)::int+1,7,1)then raise exception 'HNS_RELEASE: source fixture date outside season';end if;
  clock:=coalesce((f->>'ura')::time,'00:00'::time);local_time:=day+clock;instant:=local_time at time zone 'Europe/Zagreb';
  if(instant at time zone 'Europe/Zagreb')is distinct from local_time or((instant-interval '1 hour')at time zone 'Europe/Zagreb')=local_time or((instant+interval '1 hour')at time zone 'Europe/Zagreb')=local_time then raise exception 'HNS_RELEASE: ambiguous/nonexistent source local clock';end if;
  reason:=case when f->>'ura'is null then 'fantasy_midnight_date_only'else 'published_kickoff_offset'end;
  candidate:=instant-case when f->>'ura'is null then interval '0'else make_interval(hours=>p_offset)end;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('sourceMatchId',e.source_match_id,'sourceDate',day,'sourceKickoff',f->>'ura','timeZone','Europe/Zagreb','kind',reason,'deadlineAt',candidate));
  if earliest is null or candidate<earliest then earliest:=candidate;winner:=reason;end if;
  first_day:=least(first_day,day);
 end loop;
 if earliest is null then raise exception 'HNS_RELEASE: round has no published source date';end if;
 return jsonb_build_object('deadlineAt',earliest,'playedOn',first_day,'reason',winner,'candidates',candidates);
end $$;
revoke all on function private_hns_women_release.source_deadline(text,int,jsonb,int)from public,anon,authenticated,service_role;

create function private_hns_women_release.guard_round()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare protected boolean:=false;
begin
 if tg_op='DELETE'then
  if exists(select 1 from private_hns_women_release.round_sources where round_id=old.id or competition_id=old.competition_id)or exists(select 1 from competitions where id=old.competition_id and slug='hr-prva-hnlz'and source='hns'and source_league_code='114471579'and source_policy='hr-hnlz-v1'and date_only_deadline_policy='midnight-local-v1')then raise exception 'HNS_RELEASE: reviewed round cannot be deleted/recreated';end if;
  return old;
 end if;
 if tg_op='UPDATE'then select exists(select 1 from private_hns_women_release.round_sources where round_id=old.id)into protected;end if;
 protected:=protected or exists(select 1 from private_hns_women_release.round_sources where competition_id=new.competition_id)or exists(select 1 from competitions where id=new.competition_id and slug='hr-prva-hnlz'and source='hns'and source_league_code='114471579'and source_policy='hr-hnlz-v1'and date_only_deadline_policy='midnight-local-v1');
 if not protected then return new;end if;
 if tg_op='UPDATE'then
  if row(new.competition_id,new.season,new.number)is distinct from row(old.competition_id,old.season,old.number)then raise exception 'HNS_RELEASE: reviewed round identity immutable';end if;
  if old.lineups_locked_at is not null and new.lineups_locked_at is distinct from old.lineups_locked_at then raise exception 'HNS_RELEASE: locked lineup timestamp cannot reopen/change';end if;
  if row(new.played_on,new.deadline_at)is not distinct from row(old.played_on,old.deadline_at)then return new;end if;
  if old.lineups_locked_at is not null or old.deadline_at<=clock_timestamp()then raise exception 'HNS_RELEASE: locked/expired round cannot reopen or change';end if;
  if new.deadline_at>old.deadline_at then raise exception 'HNS_RELEASE: deadline can only move earlier';end if;
 end if;
 if not exists(select 1 from private_hns_women_release.round_authorizations where competition_id=new.competition_id and season=new.season and number=new.number and authorized_xid=txid_current()and played_on=new.played_on and deadline_at=new.deadline_at)then raise exception 'HNS_RELEASE: exact private round authorization required';end if;
 return new;
end $$;
revoke all on function private_hns_women_release.guard_round()from public,anon,authenticated,service_role;
create trigger hns_women_round_deadline before insert or update or delete on public.rounds for each row execute function private_hns_women_release.guard_round();

create function public.update_hns_women_round(p_competition_id bigint,p_source_competition_id text,p_round int,p_fixtures jsonb,p_source_sha256 text,p_captured_at timestamptz)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare c competitions%rowtype;r rounds%rowtype;s private_hns_women_release.round_sources%rowtype;v_season text;d jsonb;effective jsonb;document jsonb;day date;due timestamptz;
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'HNS_RELEASE: READ COMMITTED required';end if;
 select *into c from competitions where id=p_competition_id for update;
 if c.id is null or c.slug<>'hr-prva-hnlz'or c.source<>'hns'or c.source_league_code is distinct from '114471579'or c.source_policy is distinct from 'hr-hnlz-v1'or c.date_only_deadline_policy is distinct from 'midnight-local-v1'or c.rok_pomak_ur<>6 or not exists(select 1 from countries where id=c.country_id and code='HR')then raise exception 'HNS_RELEASE: exact new-league cutoff opt-in required';end if;
 perform 1 from countries where id=c.country_id and code='HR'for share;
 if not found then raise exception 'HNS_RELEASE: source country changed';end if;
 if p_source_sha256 is null or p_source_sha256!~'^[a-f0-9]{64}$'or p_captured_at is null or not isfinite(p_captured_at)or p_captured_at>clock_timestamp()+interval '5 minutes'or p_captured_at<clock_timestamp()-(case p_source_competition_id when '108043476'then interval '168 hours'else interval '12 hours'end)then raise exception 'HNS_RELEASE: fresh original source SHA/capture time required';end if;
 d:=private_hns_women_release.source_deadline(p_source_competition_id,p_round,p_fixtures,c.rok_pomak_ur);day:=(d->>'playedOn')::date;due:=(d->>'deadlineAt')::timestamptz;
 v_season:=case p_source_competition_id when '114471579'then '2026/27'when '108043476'then '2025/26'end;
 if v_season is null or(c.active and v_season<>'2026/27')then raise exception 'HNS_RELEASE: archive round changes only during inactive bootstrap';end if;
 select *into r from rounds where competition_id=c.id and rounds.season=v_season and number=p_round for update;
 if r.id is not null and(r.lineups_locked_at is not null or r.deadline_at<=clock_timestamp())then return jsonb_build_object('roundId',r.id,'playedOn',r.played_on,'deadlineAt',r.deadline_at,'retained','locked_or_expired');end if;
 select *into s from private_hns_women_release.round_sources where round_id=r.id;
 document:=d||jsonb_build_object('sourceCompetitionId',p_source_competition_id,'rawSha256',p_source_sha256,'capturedAt',p_captured_at,'fixtures',p_fixtures);
 effective:=document;
 if r.id is not null and r.deadline_at is null then raise exception 'HNS_RELEASE: existing unknown deadline cannot silently acquire a future cutoff';end if;
 if r.id is not null and r.deadline_at<due then
  if s.round_id is null or(s.effective_document->>'deadlineAt')::timestamptz is distinct from r.deadline_at then raise exception 'HNS_RELEASE: existing earlier cutoff lacks source provenance';end if;
  due:=r.deadline_at;effective:=s.effective_document;
 end if;
 if r.id is null and c.active and due<=clock_timestamp()then raise exception 'HNS_RELEASE: cannot create expired rounds after launch';end if;
 insert into private_hns_women_release.round_authorizations values(c.id,v_season,p_round,txid_current(),day,due)on conflict(competition_id,season,number,authorized_xid)do update set played_on=excluded.played_on,deadline_at=excluded.deadline_at;
 if r.id is null then
  insert into rounds(competition_id,season,number,played_on,deadline_at)values(c.id,v_season,p_round,day,due)returning *into r;
 else
  update rounds set played_on=day,deadline_at=due where id=r.id and lineups_locked_at is null and deadline_at>clock_timestamp()returning *into r;
  if r.id is null then raise exception 'HNS_RELEASE: round changed/expired during cutoff update';end if;
 end if;
 insert into private_hns_women_release.round_sources values(r.id,c.id,v_season,p_round,effective,document)on conflict(round_id)do update set effective_document=excluded.effective_document,latest_document=excluded.latest_document;
 return jsonb_build_object('roundId',r.id,'playedOn',r.played_on,'deadlineAt',r.deadline_at,'reason',effective->>'reason','sourceKickoffPublished',not exists(select 1 from jsonb_array_elements(effective->'candidates')x where x->>'sourceKickoff'is null));
end $$;
revoke all on function public.update_hns_women_round(bigint,text,int,jsonb,text,timestamptz)from public,anon,authenticated;
grant execute on function public.update_hns_women_round(bigint,text,int,jsonb,text,timestamptz)to service_role;
